buggy.count_nonzero_axis_non_dia:
import numpy as np
import scipy.sparse as sp

M = np.array([[1, 0, 2],
              [0, 0, 3],
              [4, 0, 0]], dtype=np.int8)
base = sp.csr_matrix(M)

for fmt in ["coo", "csr", "csc", "lil", "bsr", "dok"]:
    A = base.asformat(fmt)
    for ax in (0, 1):
        try:
            res = np.asarray(A.count_nonzero(axis=ax)).ravel()
        except Exception:
            res = None
        for i in range(3):
            if res is None or i >= res.size:
                v = float("nan")
            else:
                v = float(res[i])
            probe("cz_%s_axis%d_%d" % (fmt, ax, i), v)

